-- YG-1296 entegrasyon tanımı ve üretime açma onayı; YG-1306 askıya alma ve yeniden açma ölçütü.
CREATE TABLE entegrasyon_tanimi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), ad text NOT NULL UNIQUE, gonderen_sistem text NOT NULL, alan_sistem text NOT NULL, kayit_sahibi text NOT NULL, tetikleyici text NOT NULL, siklik text NOT NULL, bilgi_sinifi text NOT NULL CHECK (bilgi_sinifi IN ('Kamuya Açık', 'Kurumsal', 'Gizli', 'Kritik')), hata_sorumlusu text NOT NULL, hizmet_beklentisi text NOT NULL, paylasim_amaci text NOT NULL, durum text NOT NULL DEFAULT 'Taslak' CHECK (durum IN ('Taslak', 'Onayda', 'Üretimde', 'Askıda', 'Kapalı')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), uretim_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
CREATE TABLE entegrasyon_askisi (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), entegrasyon_ref uuid NOT NULL REFERENCES entegrasyon_tanimi (kimlik), neden text NOT NULL CHECK (neden IN ('Güvenlik Olayı', 'Ciddi Veri Uyuşmazlığı')), aciklama text NOT NULL, etkilenen_isler text NOT NULL, gecici_yontem text NOT NULL, kullanici_bildirimi text NOT NULL, yeniden_acma_olcutu text NOT NULL, askiya_alan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), askiya_alma_zamani timestamptz NOT NULL DEFAULT now(), acilis_zamani timestamptz, acan_ref text REFERENCES kullanici_hesabi (kimlik), acilis_gerekcesi text);
GRANT SELECT, INSERT, UPDATE ON entegrasyon_tanimi, entegrasyon_askisi TO yatonet_uygulama;
